CREATE TABLE voice_clue_candidates (id VARCHAR(36) PRIMARY KEY, case_id VARCHAR(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, voice_report_id VARCHAR(36) NULL REFERENCES voice_reports(id) ON DELETE SET NULL, intercom_recording_id VARCHAR(36) NULL REFERENCES intercom_recordings(id) ON DELETE SET NULL, submitted_by_user_id VARCHAR(36) NOT NULL REFERENCES users(id), discoverer_user_id VARCHAR(36) NULL REFERENCES users(id), source_type VARCHAR(40) NOT NULL, ai_generated BOOLEAN NOT NULL DEFAULT TRUE, transcript_text TEXT NULL, candidate_json TEXT NOT NULL, asr_version VARCHAR(100) NULL, model_version VARCHAR(100) NULL, status VARCHAR(20) NOT NULL CHECK (status IN ('queued','processing','pending_review','confirmed','rejected','failed')), retry_count INTEGER NOT NULL DEFAULT 0, failure_reason TEXT NULL, promoted_clue_id VARCHAR(36) NULL REFERENCES clues(id) ON DELETE SET NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
-- statement-break
CREATE INDEX idx_voice_clue_candidates_case_status ON voice_clue_candidates(case_id, status, created_at);
